/* ===== OpenLearnHub — Shared Design System ===== */

/* ---------- Reset & Base ---------- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy:   #0a0a23;
  --gold:   #feac32;
  --blue:   #002ead;
  --white:  #ffffff;
  --bg:     #f5f6f7;
  --text:   #1b1b32;
  --muted:  #6b6b7b;
  --border: #d0d0d8;
  --card-bg:#ffffff;
  --radius: 6px;
  --shadow: 0 2px 12px rgba(0,0,0,.08);
  --font:   'Inter', system-ui, -apple-system, sans-serif;
}

html { font-size: 16px; scroll-behavior: smooth; }
body { font-family: var(--font); color: var(--text); background: var(--bg); line-height: 1.6; }

a { color: var(--blue); text-decoration: none; }
a:hover { text-decoration: underline; }
img { display: block; max-width: 100%; }
button { cursor: pointer; font-family: var(--font); }
ul { list-style: none; }

/* ---------- Layout ---------- */
.container { max-width: 1140px; margin: 0 auto; padding: 0 20px; }
.section { padding: 48px 0; }

/* ---------- Header ---------- */
.site-header {
  background: var(--navy);
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: 0 2px 8px rgba(0,0,0,.3);
}
.header-inner {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 0 20px;
  height: 56px;
  max-width: 1140px;
  margin: 0 auto;
}
.site-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--white);
  font-weight: 700;
  font-size: 1.05rem;
  white-space: nowrap;
  flex-shrink: 0;
}
.logo-icon {
  width: 32px; height: 32px;
  background: var(--gold);
  border-radius: 6px;
  display: flex; align-items: center; justify-content: center;
  color: var(--navy); font-weight: 900; font-size: .9rem;
}
.search-bar {
  flex: 1;
  max-width: 480px;
  position: relative;
}
.search-bar input {
  width: 100%;
  padding: 8px 14px 8px 36px;
  border-radius: 20px;
  border: none;
  background: rgba(255,255,255,.12);
  color: var(--white);
  font-size: .875rem;
  font-family: var(--font);
  outline: none;
  transition: background .2s;
}
.search-bar input::placeholder { color: rgba(255,255,255,.55); }
.search-bar input:focus { background: rgba(255,255,255,.2); }
.search-icon {
  position: absolute; left: 10px; top: 50%; transform: translateY(-50%);
  color: rgba(255,255,255,.55); font-size: .9rem; pointer-events: none;
}
.header-nav { display: flex; align-items: center; gap: 4px; margin-left: auto; }
.header-nav a {
  color: rgba(255,255,255,.85);
  padding: 6px 12px;
  border-radius: var(--radius);
  font-size: .875rem;
  font-weight: 500;
  transition: background .15s, color .15s;
}
.header-nav a:hover, .header-nav a.active { background: rgba(255,255,255,.1); color: var(--white); text-decoration: none; }
.header-nav .donate-link {
  background: var(--gold);
  color: var(--navy) !important;
  font-weight: 700;
  padding: 6px 14px;
}
.header-nav .donate-link:hover { background: #ffc04d; text-decoration: none; }

/* Hamburger */
.hamburger { display: none; flex-direction: column; gap: 5px; background: none; border: none; padding: 4px; }
.hamburger span { display: block; width: 24px; height: 2px; background: var(--white); border-radius: 2px; transition: transform .25s, opacity .25s; }
.mobile-nav {
  display: none;
  flex-direction: column;
  background: var(--navy);
  border-top: 1px solid rgba(255,255,255,.1);
  padding: 8px 20px 16px;
}
.mobile-nav a {
  color: rgba(255,255,255,.85);
  padding: 10px 0;
  font-size: .95rem;
  font-weight: 500;
  border-bottom: 1px solid rgba(255,255,255,.07);
}
.mobile-nav a:last-child { border: none; }
.mobile-nav.open { display: flex; }

@media (max-width: 768px) {
  .hamburger { display: flex; margin-left: auto; }
  .header-nav { display: none; }
  .search-bar { max-width: 100%; }
  .site-logo span { display: none; }
}

/* ---------- Banner ---------- */
.hero-banner {
  background: var(--navy);
  color: var(--white);
  text-align: center;
  padding: 10px 20px;
  font-size: .8rem;
  letter-spacing: .02em;
}
.hero-banner a { color: var(--gold); font-weight: 600; }

/* ---------- Tags ---------- */
.tag {
  display: inline-block;
  padding: 3px 10px;
  border-radius: 20px;
  font-size: .72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .04em;
  cursor: pointer;
  transition: opacity .15s;
}
.tag:hover { opacity: .8; text-decoration: none; }
.tag-ai       { background: #e8f0ff; color: #002ead; }
.tag-scraping { background: #fff3e0; color: #c75000; }
.tag-db       { background: #e8f5e9; color: #1b5e20; }
.tag-elastic  { background: #fce4ec; color: #880e4f; }
.tag-data     { background: #f3e5f5; color: #4a148c; }
.tag-node     { background: #e0f2f1; color: #004d40; }
.tag-python   { background: #fff9c4; color: #7a5000; }
.tag-sheets   { background: #e8f5e9; color: #1b5e20; }
.tag-default  { background: #e8e8f0; color: #3a3a52; }
.tag-auto     { background: #e0f7fa; color: #006064; }

/* ---------- Article Cards ---------- */
.article-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
@media (max-width: 900px) { .article-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 580px) { .article-grid { grid-template-columns: 1fr; } }

.card {
  background: var(--card-bg);
  border-radius: 10px;
  overflow: hidden;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  transition: transform .2s, box-shadow .2s;
}
.card:hover { transform: translateY(-3px); box-shadow: 0 8px 24px rgba(0,0,0,.12); }

.card-thumb {
  width: 100%;
  aspect-ratio: 16/9;
  object-fit: cover;
  background: linear-gradient(135deg, #0a0a23 0%, #002ead 100%);
}
.card-thumb-placeholder {
  width: 100%;
  aspect-ratio: 16/9;
  display: flex; align-items: center; justify-content: center;
  font-size: 2.5rem;
}

.card-body { padding: 16px; flex: 1; display: flex; flex-direction: column; gap: 10px; }
.card-title {
  font-size: .95rem;
  font-weight: 700;
  color: var(--text);
  line-height: 1.4;
  flex: 1;
}
.card-title:hover { color: var(--blue); }
.card-meta { display: flex; align-items: center; gap: 8px; }
.avatar {
  width: 28px; height: 28px;
  border-radius: 50%;
  background: var(--gold);
  color: var(--navy);
  display: flex; align-items: center; justify-content: center;
  font-weight: 700;
  font-size: .7rem;
  flex-shrink: 0;
}
.author-name { font-size: .8rem; font-weight: 600; color: var(--text); }
.timestamp { font-size: .75rem; color: var(--muted); margin-left: auto; }

/* ---------- Featured Card ---------- */
.featured-card {
  position: relative;
  border-radius: 12px;
  overflow: hidden;
  background: linear-gradient(135deg, #0a0a23 0%, #002ead 100%);
  min-height: 320px;
  display: flex;
  align-items: flex-end;
  box-shadow: 0 4px 24px rgba(0,0,0,.18);
  margin-bottom: 40px;
}
.featured-overlay {
  position: absolute; inset: 0;
  background: linear-gradient(to top, rgba(10,10,35,.92) 40%, rgba(10,10,35,.2) 100%);
}
.featured-content {
  position: relative;
  padding: 32px;
  color: var(--white);
  z-index: 1;
}
.featured-label {
  display: inline-block;
  background: var(--gold);
  color: var(--navy);
  font-size: .7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .08em;
  padding: 3px 10px;
  border-radius: 20px;
  margin-bottom: 12px;
}
.featured-title { font-size: 1.5rem; font-weight: 800; line-height: 1.3; margin-bottom: 16px; max-width: 640px; }
.featured-meta { display: flex; align-items: center; gap: 10px; font-size: .85rem; color: rgba(255,255,255,.75); }
.featured-avatar {
  width: 34px; height: 34px;
  border-radius: 50%;
  background: var(--gold);
  color: var(--navy);
  display: flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: .8rem;
}
.featured-emoji {
  font-size: 80px;
  position: absolute;
  right: 40px; top: 50%; transform: translateY(-50%);
  opacity: .18;
}

/* ---------- Load More Button ---------- */
.load-more-wrap { text-align: center; padding: 32px 0 8px; }
.btn-load-more {
  background: var(--navy);
  color: var(--white);
  border: none;
  padding: 12px 36px;
  border-radius: 6px;
  font-size: .9rem;
  font-weight: 600;
  transition: background .2s;
}
.btn-load-more:hover { background: #1a1a3e; }
.btn-load-more:disabled { opacity: .5; cursor: default; }

/* ---------- Section Titles ---------- */
.section-title {
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--navy);
  margin-bottom: 24px;
  padding-bottom: 12px;
  border-bottom: 3px solid var(--gold);
  display: inline-block;
}

/* ---------- Learn Page ---------- */
.learn-hero {
  background: var(--navy);
  color: var(--white);
  padding: 48px 20px;
  text-align: center;
}
.learn-hero h1 { font-size: 2rem; font-weight: 800; margin-bottom: 12px; }
.learn-hero p { color: rgba(255,255,255,.75); font-size: 1rem; max-width: 520px; margin: 0 auto 20px; }
.btn-signin {
  background: var(--gold);
  color: var(--navy);
  border: none;
  padding: 10px 28px;
  border-radius: 6px;
  font-weight: 700;
  font-size: .9rem;
  display: inline-block;
}
.btn-signin:hover { background: #ffc04d; text-decoration: none; }

.curriculum-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 20px;
  margin-top: 24px;
}
.cert-card {
  background: var(--card-bg);
  border-radius: 10px;
  padding: 24px;
  box-shadow: var(--shadow);
  border-left: 4px solid var(--gold);
  display: flex;
  align-items: flex-start;
  gap: 16px;
  transition: transform .2s, box-shadow .2s;
}
.cert-card:hover { transform: translateY(-2px); box-shadow: 0 6px 20px rgba(0,0,0,.1); }
.cert-icon { font-size: 1.8rem; flex-shrink: 0; }
.cert-info h3 { font-size: .95rem; font-weight: 700; color: var(--navy); margin-bottom: 4px; }
.cert-info p  { font-size: .8rem; color: var(--muted); }
.cert-info a  { font-size: .8rem; color: var(--blue); font-weight: 600; }

.challenge-box {
  background: linear-gradient(135deg, var(--navy), #001a7a);
  color: var(--white);
  border-radius: 12px;
  padding: 32px;
  display: flex; align-items: center; justify-content: space-between; gap: 20px;
  flex-wrap: wrap;
}
.challenge-box h2 { font-size: 1.2rem; font-weight: 800; margin-bottom: 8px; }
.challenge-box p  { color: rgba(255,255,255,.75); font-size: .875rem; max-width: 380px; }
.challenge-links { display: flex; flex-direction: column; gap: 10px; }
.btn-challenge {
  background: var(--gold);
  color: var(--navy);
  border: none;
  padding: 10px 24px;
  border-radius: 6px;
  font-weight: 700;
  font-size: .875rem;
  text-align: center;
  white-space: nowrap;
  transition: background .2s;
}
.btn-challenge:hover { background: #ffc04d; text-decoration: none; }
.btn-challenge-outline {
  background: transparent;
  color: var(--white);
  border: 2px solid rgba(255,255,255,.4);
  padding: 9px 24px;
  border-radius: 6px;
  font-weight: 600;
  font-size: .875rem;
  text-align: center;
  transition: border-color .2s;
}
.btn-challenge-outline:hover { border-color: var(--white); text-decoration: none; }

.resource-section { background: var(--white); border-radius: 10px; padding: 28px; box-shadow: var(--shadow); }
.resource-section h2 { font-size: 1.05rem; font-weight: 700; color: var(--navy); margin-bottom: 16px; border-bottom: 2px solid var(--gold); padding-bottom: 8px; display: inline-block; }
.resource-list { display: flex; flex-direction: column; gap: 10px; }
.resource-item { display: flex; align-items: center; gap: 10px; padding: 8px 0; border-bottom: 1px solid var(--border); }
.resource-item:last-child { border: none; }
.resource-icon { font-size: 1.2rem; }
.resource-item a { font-size: .875rem; font-weight: 600; color: var(--blue); }
.resource-item span { font-size: .75rem; color: var(--muted); margin-left: auto; }
.resource-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 20px; }

/* ---------- Donate Page ---------- */
.donate-hero {
  background: linear-gradient(135deg, var(--navy), #001a7a);
  color: var(--white);
  padding: 60px 20px;
  text-align: center;
}
.donate-hero h1 { font-size: 2.2rem; font-weight: 900; margin-bottom: 16px; }
.donate-hero p { color: rgba(255,255,255,.8); font-size: 1rem; max-width: 600px; margin: 0 auto; line-height: 1.7; }

.donation-box {
  background: var(--white);
  border-radius: 16px;
  padding: 36px;
  box-shadow: 0 8px 32px rgba(0,0,0,.12);
  max-width: 520px;
  margin: -40px auto 0;
  position: relative;
  z-index: 2;
}
.amount-tabs { display: flex; gap: 10px; margin-bottom: 20px; }
.amount-tab {
  flex: 1;
  padding: 12px 8px;
  border: 2px solid var(--border);
  border-radius: 8px;
  background: none;
  font-size: 1rem;
  font-weight: 700;
  color: var(--text);
  transition: border-color .15s, background .15s, color .15s;
}
.amount-tab.active {
  border-color: var(--gold);
  background: #fff8e1;
  color: var(--navy);
}
.amount-tab:hover:not(.active) { border-color: var(--navy); }

.donation-desc {
  font-size: .9rem;
  color: var(--muted);
  margin-bottom: 20px;
  min-height: 48px;
  line-height: 1.5;
  transition: opacity .2s;
}
.donation-desc strong { color: var(--navy); }

.btn-donate {
  width: 100%;
  background: var(--gold);
  color: var(--navy);
  border: none;
  padding: 14px;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 800;
  letter-spacing: .02em;
  transition: background .2s;
}
.btn-donate:hover { background: #ffc04d; }
.donate-sub { text-align: center; font-size: .78rem; color: var(--muted); margin-top: 10px; }
.donate-sub a { color: var(--blue); }

.benefits-section { padding: 60px 0 48px; }
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 20px;
  margin-top: 24px;
}
.benefit-card {
  background: var(--white);
  border-radius: 10px;
  padding: 24px;
  box-shadow: var(--shadow);
  text-align: center;
}
.benefit-icon { font-size: 2rem; margin-bottom: 10px; }
.benefit-card p { font-size: .875rem; color: var(--muted); line-height: 1.5; }

.initiatives-section { background: var(--navy); color: var(--white); padding: 56px 0; }
.initiatives-section .section-title { color: var(--gold); }
.initiatives-list { display: flex; flex-direction: column; gap: 14px; margin-top: 24px; }
.initiative-item { display: flex; align-items: center; gap: 14px; font-size: .9rem; color: rgba(255,255,255,.85); }
.initiative-bullet { width: 8px; height: 8px; background: var(--gold); border-radius: 50%; flex-shrink: 0; }

.stats-section { padding: 56px 0; background: var(--bg); }
.stats-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 24px; margin-top: 24px; }
.stat-card { background: var(--white); border-radius: 10px; padding: 28px; box-shadow: var(--shadow); text-align: center; }
.stat-number { font-size: 2rem; font-weight: 900; color: var(--navy); }
.stat-label  { font-size: .8rem; color: var(--muted); margin-top: 4px; }

/* FAQ */
.faq-section { padding: 56px 0; }
.faq-list { max-width: 720px; margin: 24px auto 0; display: flex; flex-direction: column; gap: 0; border-radius: 10px; overflow: hidden; box-shadow: var(--shadow); }
.faq-item { background: var(--white); border-bottom: 1px solid var(--border); }
.faq-item:last-child { border: none; }
.faq-question {
  width: 100%;
  background: none;
  border: none;
  text-align: left;
  padding: 18px 24px;
  font-size: .9rem;
  font-weight: 600;
  color: var(--text);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  transition: background .15s;
}
.faq-question:hover { background: #f8f8fc; }
.faq-chevron { transition: transform .25s; font-size: .75rem; color: var(--muted); flex-shrink: 0; }
.faq-item.open .faq-chevron { transform: rotate(180deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height .3s ease, padding .3s;
  padding: 0 24px;
  font-size: .875rem;
  color: var(--muted);
  line-height: 1.7;
}
.faq-item.open .faq-answer { max-height: 300px; padding: 0 24px 18px; }

/* ---------- Tag Pages ---------- */
.tag-hero { background: var(--bg); padding: 36px 0 0; border-bottom: 1px solid var(--border); }
.tag-name { font-size: 2rem; font-weight: 900; color: var(--navy); }
.tag-count { color: var(--muted); font-size: .9rem; margin-top: 4px; margin-bottom: 20px; }

.popular-tags-bar { padding: 16px 0 20px; }
.popular-tags-bar h3 { font-size: .8rem; font-weight: 700; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); margin-bottom: 12px; }
.tags-scroll { display: flex; flex-wrap: wrap; gap: 8px; }
.tag-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 12px;
  border: 1.5px solid var(--border);
  border-radius: 20px;
  font-size: .78rem;
  font-weight: 600;
  color: var(--text);
  background: var(--white);
  cursor: pointer;
  transition: border-color .15s, background .15s;
}
.tag-chip:hover { border-color: var(--navy); background: var(--bg); text-decoration: none; }
.tag-chip-count { color: var(--muted); font-weight: 400; }

/* ---------- Footer ---------- */
.site-footer { background: var(--navy); color: rgba(255,255,255,.7); padding: 48px 0 24px; font-size: .82rem; }
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 36px;
}
@media (max-width: 720px) { .footer-grid { grid-template-columns: 1fr; } }
.footer-brand .site-logo { margin-bottom: 14px; }
.footer-brand p { line-height: 1.6; max-width: 340px; color: rgba(255,255,255,.6); }
.footer-col h4 { font-size: .85rem; font-weight: 700; color: var(--white); margin-bottom: 14px; letter-spacing: .04em; text-transform: uppercase; }
.footer-col a { display: block; color: rgba(255,255,255,.6); padding: 3px 0; transition: color .15s; }
.footer-col a:hover { color: var(--gold); text-decoration: none; }
.footer-tags { display: flex; flex-wrap: wrap; gap: 6px; }
.footer-tag { background: rgba(255,255,255,.08); color: rgba(255,255,255,.65); padding: 3px 10px; border-radius: 12px; font-size: .75rem; cursor: pointer; }
.footer-tag:hover { background: rgba(255,255,255,.15); text-decoration: none; }
.footer-bottom { border-top: 1px solid rgba(255,255,255,.1); padding-top: 20px; display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 10px; }
.footer-bottom p { color: rgba(255,255,255,.45); font-size: .77rem; }
.footer-links { display: flex; flex-wrap: wrap; gap: 12px; }
.footer-links a { color: rgba(255,255,255,.5); font-size: .77rem; }
.footer-links a:hover { color: var(--gold); text-decoration: none; }

/* ---------- Utilities ---------- */
.mt-8  { margin-top:  8px; }
.mt-16 { margin-top: 16px; }
.mt-24 { margin-top: 24px; }
.mt-40 { margin-top: 40px; }
.mb-8  { margin-bottom:  8px; }
.mb-24 { margin-bottom: 24px; }
.text-center { text-align: center; }
.hidden { display: none !important; }

